    run([sys.executable,root/'tests/test_onboarding.py'],env=env,timeout=180)
    run([sys.executable,root/'tests/test_migration.py'],env=env,timeout=180)
    run([sys.executable,'launch.py','--version'],cwd=pkg,env=env)
