        src=stage/'source';shutil.copytree(root/'source',src,ignore=shutil.ignore_patterns('__pycache__','*.pyc'));shutil.copy2(work/'pyproject.toml',src/'pyproject.toml');shutil.copy2(go/'go.mod',src/'go/go.mod');shutil.copy2(go/'go.sum',src/'go/go.sum');write(src/'LICENSE',license_text)
        write(stage/'SHA256SUMS.txt',''.join(f'{sha(p)}  {p.name}\n' for p in sorted(stage.iterdir()) if p.is_file()))
