def assemble(dirs,out,repo):
    if out.exists():raise RuntimeError('Assembly output exists; choose another path')
    manifests=[];runtimes={};license_text=None
    for d in dirs:
        m=json.loads((d/'manifest.json').read_text());key=m['os']+'-'+m['arch'];runtime=d/'runtime'
        if m['version']!=NPM_VERSION or m['repo']!=repo or key in runtimes or key not in ('darwin-arm64','darwin-x64','linux-arm64','linux-x64'):raise RuntimeError('Incompatible target manifest')
        if sha(d/m['archive'])!=m['sha256']:raise RuntimeError('Archive checksum mismatch')
        actual={p.name:sha(p) for p in runtime.iterdir() if p.is_file()}
        if actual!=m['runtime_hashes'] or any(not p.is_file() or p.is_symlink() for p in runtime.iterdir()):raise RuntimeError('Runtime integrity mismatch')
        lic=(runtime/'LICENSE').read_text();
        if license_text is not None and license_text!=lic:raise RuntimeError('License mismatch')
